class Demo
  private owned _pool: OwningArray<Res> := [new Res(), new Res()];
  public method TakeFirst(): owned Res
    var t := move _pool[0];   // slot 0 vacated (§28.8.1)
    _pool.Clear();            // §28.11: a restoration; stdlib §4.5 Clear: `move _storage[0]` faults
    return t;                 //   (checked) or `item!` raises NullReferenceException (unchecked)
  end TakeFirst;
  public static method Rotate()
    using var pool := new OwningArray<Res>();   // call-admitting window
    pool.Add(new Res()); pool.Add(new Res());
    var k := 0;
    var bump := lambda() => do k := 1; end;
    var t := move pool[k];    // k: not reassigned by *this body* in the window
    bump();                   // k = 1
    pool[k] := t;             // "restoring" store: no dispose of slot 1's live Res → leak
  end Rotate;
end Demo;

