class Demo
  public static method Make(): owned Res
    try
      using var b := new Boom();      // established in the try block
      if true then
        return new Res(1);            // slot established in the if-block's scope
      end;                            // the if-block's exit completes normally
    catch
      InvalidOperationException => Console.WriteLine("caught in callee");
    end;                              // b raises at the try block's exit
    return new Res(3);
  end Make;
  public static method Main()  using var r := Make();  end Main;
end Demo;
// The raise never was inside the `return` statement's scope. A: "closed 1" before
// "caught in callee". B (scope = the method body): Res(1) is never disposed.

